sys_ui_action.script:
if (current.hr_service.value == "refusal_to_work") {
    current.update();
    if (current.ohs_user == "")
        gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.ohs_user"));

    if (current.ohs_comment == "")
        gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.ohs_comment"));
    action.setRedirectURL(current);
    if (current.ohs_user != "" && current.ohs_comment != "") {
        createHRRecord_RefusalToWork(); // Create RP stage III (Refusal of dangerous work)
        current.state = 108;
        current.update();
        action.setRedirectURL(current);
    }
}

    if (current.hr_service.value == "internal_safety_complaint") {
        createHRRecord_SafetyComplaint(); // Create RP (Safety Complaint Stage 3)
        current.state = 108;
        current.update();
        action.setRedirectURL(current);
    }

    function createHRRecord_RefusalToWork() {
        var grTask = new GlideRecord("sn_hr_core_task");
        grTask.initialize();
        grTask.parent = current.sys_id;
        grTask.hr_task_type = "submit_catalog_item";
        grTask.state = 18;
        grTask.assigned_to = current.subject_person;
        grTask.short_description = "Refusal to work employee validation - stage III";
        grTask.sc_cat_item = "da183f6687d53010b7cac956cebb35b7"; //Refusal to work employee validation stage III
        grTask.insert();
    }

    function createHRRecord_SafetyComplaint() {
        var grTask = new GlideRecord("sn_hr_core_task");
        grTask.initialize();
        grTask.parent = current.sys_id;
        grTask.hr_task_type = "submit_catalog_item";
        grTask.state = 18;
        grTask.assigned_to = current.subject_person;
        grTask.short_description = "Safety Complaint employee validation - stage III";
        grTask.sc_cat_item = "df5b84f387bdf810b7cac956cebb35c4"; //Safety Complaint validation stage 3
        grTask.insert();
    }
